  display: flex;
  flex-direction: column;
  gap: 14px;
}

.form-card {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 14px 16px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--surface);
}

.card-title {
  margin: 0;
  color: var(--ink);
  font-size: 13px;
  font-weight: 600;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.field-label {
  color: var(--ink-3);
  font-size: 10px;
  letter-spacing: 0.03em;
}

.form-description {
  height: auto;
  padding: 7px 10px;
  line-height: 1.6;
  resize: vertical;
}

.editor-errors {
  padding: 10px 14px;
  border: 1px solid var(--line);
  border-left: 3px solid var(--red);
  border-radius: 10px;
  background: var(--surface);
}

.error-line {
  margin: 2px 0;
  color: var(--red);
  font-size: 11.5px;
  line-height: 1.6;
}

/* 线性步骤列表：左侧轨道圆点 + 连接竖线，不做拖拽。 */
.step-list {
  display: flex;
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
}

.step-item {
  position: relative;
  padding: 0 0 14px 24px;
}

.step-item:last-child {
  padding-bottom: 0;
}

.step-item::after {
  content: '';
  position: absolute;
  left: 4px;
  top: 13px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  border: 2px solid var(--ink-3);
  background: var(--surface);
}

.step-item:not(:last-child)::before {
  content: '';
  position: absolute;
  left: 9px;
  top: 26px;
  bottom: 0;
  width: 2px;
  background: var(--line);
}

.steps-empty {
  margin: 0;
  color: var(--ink-3);
  font-size: 11.5px;
}

.step-add-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding-top: 12px;
  border-top: 1px dashed var(--line);
}

.step-add-row .input {
  min-width: 220px;
}
